1	export function addTodo(items, title, id) {
2	  const cleaned = title.trim();
3	  if (!cleaned || cleaned.length > 100) return items;
4	  return [...items, { id, title: cleaned, completed: false }];
5	}
6	export function toggleTodo(items, id) {
7	  return items.map(item => item.id === id ? { ...item, completed: !item.completed } : item);
8	}
9	export function removeTodo(items, id) {
10	  return items.filter(item => item.id !== id);
11	}
